WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY shipping_fee, id) AS row_seq, RANK() OVER (PARTITION BY store_id, channel ORDER BY shipping_fee) AS shipping_fee_rank, FIRST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY store_id, channel ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM orders) SELECT s.id, s.store_id, s.order_date, s.channel, s.discount, s.shipping_fee, s.row_seq, s.shipping_fee_rank, s.first_known_channel, CASE WHEN channel RLIKE '^(web|store)$' THEN 'GROUP_A' WHEN channel RLIKE '^(mobile|partner)$' THEN 'GROUP_B' ELSE 'CORE' END AS channel_zone, (SELECT SUM(t2.quantity) FROM inventory t2 WHERE t2.store_id = s.store_id) AS sum_inventory_quantity FROM scored s ORDER BY discount NULLS LAST, sum_inventory_quantity
